"},"$:/plugins/rimir/mindmap/overlay-store.js":{"title":"$:/plugins/rimir/mindmap/overlay-store.js","text":"/*\
title: $:/plugins/rimir/mindmap/overlay-store.js
type: application/javascript
module-type: library

Reads, parses and persists overlay op logs. An overlay tiddler's `text` field
holds a JSON array of Op objects.

Writes are debounced (default 250 ms) so a drag gesture that emits many
intermediate events collapses to a single tiddler save - filesystem-watcher
and git-int would otherwise pick up every pointermove as a change.

The store does NOT interpret ops - that is the composer's job. It only
loads/saves and offers an append helper.

\*/

"use strict";

var DEFAULT_DEBOUNCE_MS = 250;

function readOps(wiki, title) {
    if (!title) { return []; }
    var text = wiki.getTiddlerText(title);
    if (!text) { return []; }
    try {
        var parsed = JSON.parse(text);
        return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
        // Surface as empty - widget will display a toolbar warning.
        return [];
    }
}

function writeOps(wiki, title, ops) {
    if (!title) { return; }
    var existing = wiki.getTiddler(title);
    var fields = existing ? Object.create(null) : { type: "application/json" };
    if (existing) {
        for (var k in existing.fields) { fields[k] = existing.fields[k]; }
        if (!fields.type) { fields.type = "application/json"; }
    }
    fields.title = title;
    fields.text = JSON.stringify(ops, null, 2);
    wiki.addTiddler(new $tw.Tiddler(wiki.getCreationFields(), fields, wiki.getModificationFields()));
}

/*
 * Store factory. Each $mindmap widget gets its own store bound to one
 * overlay tiddler title.
 *
 *   var store = createStore(wiki, "MyMap/overlay", { debounceMs: 250 });
 *   store.read();                  // → [op, ...]  (fresh from wiki)
 *   store.append(op);              // → enqueues a save (debounced)
 *   store.flush();                 // → forces an immediate save
 *   store.destroy();               // → cancels pending timer
 */
exports.createStore = function(wiki, title, options) {
    options = options || {};
    var debounceMs = typeof options.debounceMs === "number" ? options.debounceMs : DEFAULT_DEBOUNCE_MS;
    var pending = null;     // buffered ops not yet written
    var timer = null;
    var destroyed = false;

    function snapshot() {
        return readOps(wiki, title);
    }

    function scheduleFlush() {
        if (destroyed || !title) { return; }
        if (timer) { return; }
        timer = setTimeout(function () {
            timer = null;
            if (destroyed) { return; }
            if (!pending) { return; }
            var ops = pending;
            pending = null;
            writeOps(wiki, title, ops);
        }, debounceMs);
    }

    return {
        read: snapshot,

        // Replace the full op log atomically.
        replace: function (ops) {
            if (destroyed || !title) { return; }
            pending = Array.isArray(ops) ? ops.slice() : [];
            scheduleFlush();
        },

        // Append a single op. Buffers in memory; coalesces drag-style
        // setAttr ops on the same id/key so multiple intermediate values
        // collapse to the final one.
        append: function (op) {
            if (destroyed || !title || !op) { return; }
            if (!pending) { pending = snapshot(); }
            if (op.op === "setAttr" && pending.length > 0) {
                var last = pending[pending.length - 1];
                if (
                    last && last.op === "setAttr" &&
                    last.id === op.id && last.key === op.key
                ) {
                    pending[pending.length - 1] = op;
                    scheduleFlush();
                    return;
                }
            }
            pending.push(op);
            scheduleFlush();
        },

        flush: function () {
            if (timer) { clearTimeout(timer); timer = null; }
            if (pending && !destroyed && title) {
                var ops = pending;
                pending = null;
                writeOps(wiki, title, ops);
            }
        },

        destroy: function () {
            destroyed = true;
            if (timer) { clearTimeout(timer); timer = null; }
            pending = null;
        }
    };
};

// Exposed for tests / direct use
exports.readOps = readOps;
exports.writeOps = writeOps;
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/mindmap/producers/filter-tree.js":{"title":"$:/plugins/rimir/mindmap/producers/filter-tree.js","text":"/*\
title: $:/plugins/rimir/mindmap/producers/filter-tree.js
type: application/javascript
module-type: mindmap-producer

Default producer for the <$mindmap filter="..."> quick form. Evaluates the
filter, splits each title on `delimiter` (default "/") and builds a tree by
nesting common prefixes. Each tree path becomes one MDOM node with id
"ft:<full-path>".

Args:
  filter      : (required) TW filter expression
  delimiter   : path separator, default "/"
  root-label  : label for the synthetic root, default "Mindmap"
  body-field  : tiddler field to attach as MDOM node.body (default "text")

\*/

"use strict";

var PRODUCER_NAME = "filter-tree";
var ID_PREFIX = "ft:";

function trim(s) { return (s || "").replace(/^\s+|\s+$/g, ""); }

function splitPath(title, delim) {
    if (!title) { return []; }
    var parts = title.split(delim);
    var out = [];
    for (var i = 0; i < parts.length; i++) {
        if (parts[i] !== "") { out.push(parts[i]); }
    }
    return out;
}

function pathId(prefix, segments) {
    return ID_PREFIX + prefix.concat(segments).join("/");
}

// Build a tree by inserting each title's path segments.
function buildTree(titles, opts, wiki) {
    var delim = opts.delimiter || "/";
    var bodyField = opts["body-field"] || "text";
    var rootPrefix = opts._rootPrefix || []; // segments stripped from each title before insertion
    var root = {
        id: ID_PREFIX + (rootPrefix.length > 0 ? rootPrefix.join("/") : "__root__"),
        label: opts["root-label"] || "Mindmap",
        children: [],
        attrs: { "core:synthetic": true }
    };
    // Index by id for O(1) lookup during insertion.
    var index = Object.create(null);
    index[root.id] = root;

    titles.forEach(function (title) {
        var full = splitPath(title, delim);
        // Strip the root prefix if it matches; otherwise insert the title verbatim.
        var segments = full.slice();
        for (var i = 0; i < rootPrefix.length; i++) {
            if (segments[0] === rootPrefix[i]) { segments.shift(); } else { break; }
        }
        if (segments.length === 0) { return; }
        var parent = root;
        var pathSoFar = rootPrefix.slice();
        for (var j = 0; j < segments.length; j++) {
            pathSoFar.push(segments[j]);
            var nodeId = pathId([], pathSoFar);
            var node = index[nodeId];
            if (!node) {
                node = {
                    id: nodeId,
                    label: segments[j],
                    children: [],
                    attrs: {}
                };
                parent.children.push(node);
                index[nodeId] = node;
            }
            parent = node;
        }
        // The leaf corresponds to the actual tiddler.
        var leaf = parent;
        leaf.attrs = leaf.attrs || {};
        leaf.attrs["core:tiddler"] = title;
        if (bodyField) {
            var tiddler = wiki.getTiddler(title);
            if (tiddler && tiddler.fields[bodyField]) {
                leaf.body = tiddler.fields[bodyField];
            }
        }
    });
    return root;
}

exports.name = PRODUCER_NAME;

exports.describe = function () {
    return {
        name: PRODUCER_NAME,
        args: [
            { key: "filter",     required: true,  description: "Filter expression returning the tiddlers to include." },
            { key: "delimiter",  default: "/",    description: "Path delimiter used to derive the tree from titles." },
            { key: "root-label", default: "Mindmap", description: "Label for the synthetic root node." },
            { key: "body-field", default: "text", description: "Tiddler field shown as node body content." }
        ]
    };
};

exports.produce = function (args, wiki) {
    args = args || {};
    var filter = trim(args.filter || "");
    if (!filter) {
        return {
            version: 1,
            root: { id: ID_PREFIX + "__empty__", label: "(no filter)", children: [] },
            meta: { producer: PRODUCER_NAME, producedAt: Date.now() }
        };
    }
    var titles = wiki.filterTiddlers(filter);
    var root = buildTree(titles, args, wiki);
    return {
        version: 1,
        root: root,
        meta: {
            producer: PRODUCER_NAME,
            producedAt: Date.now(),
            source: filter
        }
    };
};

exports.refreshFilter = function (args) {
    return (args && args.filter) ? args.filter : null;
};

// Exposed for the knowledge-tree producer and tests.
exports._buildTree = buildTree;
exports._splitPath = splitPath;
exports._idPrefix = ID_PREFIX;
