title: $:/plugins/rimir/mindmap/producers/json.js
type: application/javascript
module-type: mindmap-producer

Producer that reads MDOM verbatim from a tiddler's text field. Useful for
hand-authored or pre-computed mindmaps.

Args:
  tiddler : (required) title of the JSON-bearing tiddler

\*/

"use strict";

var PRODUCER_NAME = "json";

function trim(s) { return (s || "").replace(/^\s+|\s+$/g, ""); }

exports.name = PRODUCER_NAME;

exports.describe = function () {
    return {
        name: PRODUCER_NAME,
        args: [
            { key: "tiddler", required: true, description: "Title of a tiddler whose text field contains a valid MDOM JSON document." }
        ]
    };
};

exports.produce = function (args, wiki) {
    args = args || {};
    var title = trim(args.tiddler || "");
    if (!title) {
        throw new Error("json producer: 'tiddler' argument is required");
    }
    var text = wiki.getTiddlerText(title);
    if (!text) {
        throw new Error("json producer: tiddler '" + title + "' is empty or missing");
    }
    var mdom;
    try {
        mdom = JSON.parse(text);
    } catch (e) {
        throw new Error("json producer: invalid JSON in '" + title + "': " + e.message);
    }
    if (!mdom || !mdom.root) {
        throw new Error("json producer: '" + title + "' does not contain a root MDOM node");
    }
    // Stamp meta so downstream callers can tell where the document came from.
    mdom.meta = mdom.meta || {};
    mdom.meta.producer = PRODUCER_NAME;
    mdom.meta.producedAt = Date.now();
    mdom.meta.source = title;
    return mdom;
};

exports.refreshFilter = function (args) {
    var title = args && trim(args.tiddler || "");
    return title ? "[[" + title + "]]" : null;
};
","type":"application/javascript","module-type":"mindmap-producer"},"$:/plugins/rimir/mindmap/producers/knowledge-tree.js":{"title":"$:/plugins/rimir/mindmap/producers/knowledge-tree.js","text":"/*\
title: $:/plugins/rimir/mindmap/producers/knowledge-tree.js
type: application/javascript
module-type: mindmap-producer

Producer for the rimir/knowledge-app data model. Builds an MDOM tree from
title-path segmentation of all notes under an area, enriched with type icons
and area colour from knowledge-app's metadata tiddlers.

Args:
  area        : (required) area id (e.g. "llm", "health"). Resolves to the
                area tiddler tagged $:/tags/rimir/knowledge-app/area whose
                "area-id" field matches. Determines the title prefix used as
                the tree root.
  delimiter   : path delimiter, default "/"
  include-areas-root : if "yes", build a tree of ALL areas; `area` is ignored.

Node IDs are prefixed "kt:". Tiddler-bearing nodes get attrs:
  core:tiddler  — the source title
  core:icon     — emoji from knowledge-app's type registry (when kn.type matches)
  core:color    — colour from the area's `color` field
  core:caption  — area caption for the root

\*/

"use strict";

var filterTree = require("$:/plugins/rimir/mindmap/producers/filter-tree.js");
var sanitizeLib = require("$:/plugins/rimir/mindmap/lib/sanitize-title.js");
var slideTiddlers = require("$:/plugins/rimir/mindmap/lib/slide-tiddlers.js");

var PRODUCER_NAME = "knowledge-tree";
var ID_PREFIX = "kt:";
var TYPES_TIDDLER = "$:/config/rimir/knowledge-app/types";
var AREA_TAG = "$:/tags/rimir/knowledge-app/area";
// Slide tiddlers (mindmap v0.2.7+) live under "<owner>/slides/<slug>" and
// carry this tag. They are content owned by their parent node, not structural
// nodes in the tree — exclude them from the producer's enumeration filter.
var SLIDE_TAG = "$:/tags/rimir/mindmap/slide";
// IDs starting with __ are synthetic roots that don't correspond to any
// real tiddler (e.g. "__knowledge__" forest root, "__empty__", "__root__").
function isSyntheticId(id) {
    return !id || id.indexOf("__") === 0;
}
function titleFromId(id) {
    if (!id || id.indexOf(ID_PREFIX) !== 0) { return null; }
    var rest = id.substring(ID_PREFIX.length);
    if (isSyntheticId(rest)) { return null; }
    return rest;
}
function parentTitle(title) {
    if (!title) { return null; }
    var i = title.lastIndexOf("/");
    return i < 0 ? null : title.substring(0, i);
}
function leafSegment(title) {
    if (!title) { return null; }
    var i = title.lastIndexOf("/");
    return i < 0 ? title : title.substring(i + 1);
}

function trim(s) { return (s || "").replace(/^\s+|\s+$/g, ""); }

function readTypeIndex(wiki) {
    var text = wiki.getTiddlerText(TYPES_TIDDLER, "");
    if (!text) { return Object.create(null); }
    try {
        var arr = JSON.parse(text);
        var index = Object.create(null);
        for (var i = 0; i < arr.length; i++) {
            var entry = arr[i];
            if (entry && entry.id) { index[entry.id] = entry; }
        }
        return index;
    } catch (e) {
        return Object.create(null);
    }
}

function readAreas(wiki) {
    var titles = wiki.filterTiddlers("[all[shadows+tiddlers]tag[" + AREA_TAG + "]]");
    var areas = [];
    for (var i = 0; i < titles.length; i++) {
        var tiddler = wiki.getTiddler(titles[i]);
        if (!tiddler) { continue; }
        areas.push({
            title: titles[i],
            id: trim(tiddler.fields["area-id"] || ""),
            caption: trim(tiddler.fields.caption || ""),
            icon: trim(tiddler.fields.icon || ""),
            color: trim(tiddler.fields.color || ""),
            description: trim(tiddler.fields.description || "")
        });
    }
    return areas;
}

function findAreaById(areas, id) {
    for (var i = 0; i < areas.length; i++) {
        if (areas[i].id === id) { return areas[i]; }
    }
    return null;
}

// Recursively rewrite node ids from the filter-tree ft: prefix to kt:, and
// enrich attrs from the type / area registries.
// `opts.isAreaRoot` is true only for the area's top-level node — colour is
// applied there and not propagated to descendants, so mind-elixir's per-branch
// palette can take over below.
function enrich(node, opts) {
    if (!node) { return; }
    if (node.id && node.id.indexOf(filterTree._idPrefix) === 0) {
        node.id = ID_PREFIX + node.id.substring(filterTree._idPrefix.length);
    }
    node.attrs = node.attrs || {};
    if (opts.isAreaRoot && opts.areaColor) { node.attrs["core:color"] = opts.areaColor; }
    var sourceTitle = node.attrs["core:tiddler"];
    if (sourceTitle) {
        var tiddler = opts.wiki.getTiddler(sourceTitle);
        if (tiddler) {
            var knType = trim(tiddler.fields["kn.type"] || "");
            var typeEntry = knType && opts.typeIndex[knType];
            if (typeEntry) {
                node.attrs["core:icon"] = typeEntry.icon;
                node.attrs["kn:type"] = knType;
            }
            var knTier = trim(tiddler.fields["kn.tier"] || "");
            if (knTier) { node.attrs["kn:tier"] = knTier; }
            // Tooltip surfaced via DOM title attribute by the engine adapter.
            // Format: "Note (note)" or "Note (note) — permanent". Falls back
            // to just the kn.type id when the type isn't in the registry.
            var tipParts = [];
            if (typeEntry) { tipParts.push(typeEntry.caption + " (" + knType + ")"); }
            else if (knType) { tipParts.push(knType); }
            if (knTier) { tipParts.push("— " + knTier); }
            tipParts.push("→ " + sourceTitle);
            node.attrs["core:tooltip"] = tipParts.join(" ");
        }
    }
    var children = node.children || [];
    if (children.length === 0) { return; }
    var childOpts = opts.isAreaRoot ? Object.assign({}, opts, { isAreaRoot: false }) : opts;
    for (var i = 0; i < children.length; i++) { enrich(children[i], childOpts); }
}

// Slides-only pruning: walk the tree bottom-up; keep a node iff it has slides
// of its own OR any of its descendants (after pruning) is kept. Synthetic
// nodes never have slides directly — they only survive if a descendant does.
// The root is ALWAYS preserved so the engine has something to render even
// when no slides exist anywhere; the widget shows an empty canvas in that
// case rather than throwing.
function pruneToSlideBearing(node, wiki) {
    if (!node) { return false; }
    var children = node.children || [];
    var keptChildren = [];
    for (var i = 0; i < children.length; i++) {
        if (pruneToSlideBearing(children[i], wiki)) {
            keptChildren.push(children[i]);
        }
    }
    node.children = keptChildren;
    var sourceTitle = node.attrs && node.attrs["core:tiddler"];
    var hasOwnSlides = false;
    if (sourceTitle) {
        hasOwnSlides = slideTiddlers.getSlideTitles(wiki, sourceTitle).length > 0;
    }
    if (hasOwnSlides) {
        node.attrs = node.attrs || {};
        node.attrs["mm:has-slides"] = true;
    }
    return hasOwnSlides || keptChildren.length > 0;
}

// Rewrite each tiddler-bearing node's `label` to the value of `labelField`.
// Fallback rules:
//   labelField === "caption" and field is empty → keep the title-segment
//     label (the natural identity) and stamp `mm:label-derived = "title"`
//     so UI can style it muted.
//   any other field empty → label becomes "UNDEFINED" + stamp
//     `mm:label-status = "undefined"`. Engines can render that distinctly.
function relabelTree(node, labelField, wiki) {
    if (!node) { return; }
    var sourceTitle = node.attrs && node.attrs["core:tiddler"];
    if (sourceTitle) {
        var tiddler = wiki.getTiddler(sourceTitle);
        var raw = tiddler ? trim(tiddler.fields[labelField] || "") : "";
        if (raw) {
            node.label = raw;
        } else if (labelField === "caption") {
            node.attrs = node.attrs || {};
            node.attrs["mm:label-derived"] = "title";
        } else {
            node.label = "UNDEFINED";
            node.attrs = node.attrs || {};
            node.attrs["mm:label-status"] = "undefined";
        }
    }
    var children = node.children || [];
    for (var i = 0; i < children.length; i++) { relabelTree(children[i], labelField, wiki); }
}

exports.name = PRODUCER_NAME;

exports.describe = function () {
    return {
        name: PRODUCER_NAME,
        args: [
            { key: "area",      required: true,  description: "Knowledge area id (e.g. 'llm'). Determines the title prefix used as the tree root." },
            { key: "delimiter", default: "/",    description: "Path delimiter (default '/')" },
            { key: "include-areas-root", default: "no", description: "If 'yes', render a forest of all areas. The `area` arg is ignored." },
            { key: "label-field", default: "title", description: "Tiddler field used as the visible node label. 'title' (default) uses the leaf path-segment; 'caption' (or any other field) decouples display from the structural identity — rename only edits the chosen field, title is preserved." },
            { key: "slides-only", default: "no", description: "If 'yes', the tree is pruned to nodes that have at least one slide OR have a descendant with slides — i.e. the presentation-eligible spine of the area. Composes with focus mode (re-rooting happens first, then pruning)." }
        ]
    };
};

exports.produce = function (args, wiki) {
    args = args || {};
    var typeIndex = readTypeIndex(wiki);
    var areas = readAreas(wiki);
    var delimiter = args.delimiter || "/";

    // Forest mode: all areas under a synthetic "Knowledge" root.
    if (args["include-areas-root"] === "yes" || args["include-areas-root"] === true) {
        var rootChildren = [];
        for (var i = 0; i < areas.length; i++) {
            var area = areas[i];
            if (!area.id) { continue; }
            var areaPrefix = "knowledge" + delimiter + area.id + delimiter;
            var titles = wiki.filterTiddlers("[all[shadows+tiddlers]prefix[" + areaPrefix + "]!tag[" + SLIDE_TAG + "]]");
            var areaRoot = filterTree._buildTree(titles, {
                delimiter: delimiter,
                _rootPrefix: ["knowledge", area.id],
                "root-label": area.caption || area.id,
                "body-field": "text"
            }, wiki);
            enrich(areaRoot, { wiki: wiki, typeIndex: typeIndex, areaColor: area.color, isAreaRoot: true });
            areaRoot.attrs = areaRoot.attrs || {};
            if (area.icon) { areaRoot.attrs["core:icon"] = area.icon; }
            rootChildren.push(areaRoot);
        }
        var forestLabelField = trim(args["label-field"] || "");
        if (forestLabelField && forestLabelField !== "title") {
            for (var fri = 0; fri < rootChildren.length; fri++) {
                relabelTree(rootChildren[fri], forestLabelField, wiki);
            }
        }
        var forestRoot = {
            id: ID_PREFIX + "__knowledge__",
            label: "Knowledge",
            children: rootChildren,
            attrs: { "core:synthetic": true }
        };
        // Slides-only mode: prune every area subtree, then drop area roots that
        // have no slides remaining (forest root itself always survives).
        if (args["slides-only"] === "yes" || args["slides-only"] === true) {
            var keptAreas = [];
            for (var pi = 0; pi < forestRoot.children.length; pi++) {
                if (pruneToSlideBearing(forestRoot.children[pi], wiki)) {
                    keptAreas.push(forestRoot.children[pi]);
                }
            }
            forestRoot.children = keptAreas;
            forestRoot.attrs["mm:slides-only"] = true;
        }
        return {
            version: 1,
            root: forestRoot,
            meta: { producer: PRODUCER_NAME, producedAt: Date.now() }
        };
    }

    // Single-area mode.
    var areaId = trim(args.area || "");
    if (!areaId) {
        throw new Error("knowledge-tree: 'area' argument is required");
    }
    var areaMeta = findAreaById(areas, areaId);
    var areaPrefix = "knowledge" + delimiter + areaId;

    // Focus mode: re-root the MDOM at a deeper title under the area. The
    // focus-title arg is the full tiddler title (e.g. "knowledge/llm/agents")
    // and must be the area itself OR a descendant of it; anything else is
    // ignored (back to area-level view). When focused, the focused tiddler
    // becomes the new root and only its descendants are included.
    var focusTitle = trim(args["focus-title"] || "");
    var rootTitle;
    var rootPrefixSegments;
    var prefix;
    if (focusTitle && (focusTitle === areaPrefix || focusTitle.indexOf(areaPrefix + delimiter) === 0)
            && wiki.getTiddler(focusTitle)) {
        rootTitle = focusTitle;
        rootPrefixSegments = focusTitle.split(delimiter);
        prefix = focusTitle + delimiter;
    } else {
        rootTitle = areaPrefix;
        rootPrefixSegments = ["knowledge", areaId];
        prefix = areaPrefix + delimiter;
    }

    var titles = wiki.filterTiddlers("[all[shadows+tiddlers]prefix[" + prefix + "]!tag[" + SLIDE_TAG + "]]");

    // For the focused-subtree case we pick a label from the focus tiddler's
    // caption (or its leaf segment if no caption). For area-level view we
    // use the area's caption (existing behaviour).
    var rootLabel;
    if (focusTitle && rootTitle !== areaPrefix) {
        var focusTid = wiki.getTiddler(focusTitle);
        rootLabel = (focusTid && trim(focusTid.fields.caption || "")) || focusTitle.split(delimiter).pop();
    } else {
        rootLabel = (areaMeta && areaMeta.caption) || areaId;
    }

    var root = filterTree._buildTree(titles, {
        delimiter: delimiter,
        _rootPrefix: rootPrefixSegments,
        "root-label": rootLabel,
        "body-field": "text"
    }, wiki);
    // filter-tree skips the root tiddler itself (zero-segment path after the
    // prefix strip), so its metadata isn't attached automatically. Stamp
    // core:tiddler manually so enrich picks up the focused tiddler's icon /
    // kn.type / tooltip.
    if (wiki.getTiddler(rootTitle)) {
        root.attrs = root.attrs || {};
        root.attrs["core:tiddler"] = rootTitle;
    }
    enrich(root, { wiki: wiki, typeIndex: typeIndex, areaColor: areaMeta && areaMeta.color, isAreaRoot: true });
    root.attrs = root.attrs || {};
    if (areaMeta && areaMeta.icon) { root.attrs["core:icon"] = areaMeta.icon; }
    if (areaMeta && areaMeta.description) { root.attrs["core:description"] = areaMeta.description; }
    if (focusTitle && rootTitle !== areaPrefix) {
        root.attrs["mm:focused"] = focusTitle;
    }
    // Optional re-labeling: when the view picks a non-title field (e.g.
    // caption) as the visible label, rewrite each tiddler-bearing node's
    // label from that field. Title stays the structural identity.
    var labelField = trim(args["label-field"] || "");
    if (labelField && labelField !== "title") {
        relabelTree(root, labelField, wiki);
    }
    // Slides-only mode: prune subtrees whose entire hierarchy has zero
    // slides. The root itself is always kept (even if empty) so the engine
    // has something to render — the canvas shows just the area label with
    // no children rather than throwing.
    if (args["slides-only"] === "yes" || args["slides-only"] === true) {
        pruneToSlideBearing(root, wiki);
        root.attrs = root.attrs || {};
        root.attrs["mm:slides-only"] = true;
    }

    return {
        version: 1,
        root: root,
        meta: {
            producer: PRODUCER_NAME,
            producedAt: Date.now(),
            source: "area=" + areaId
        }
    };
};

// -------------------------------------------------------------------------
// Structural write-back path
// -------------------------------------------------------------------------
//
// The widget routes selected ops here (per structural-ops.routeOp) so the
// mindmap acts as an authoring surface for real knowledge tiddlers.
// Drag-reparent → rename tiddler title; rename → rename tiddler leaf
// segment; removeNode → delete tiddler subtree. addNode is wired up by
// Landing B (popup-edit-modal integration).

exports.capabilities = {
    structural: true,
    structuralOps: ["rename", "reparent", "removeNode", "addNode"],
    // Producer understands the `slides-only` arg — widget exposes the
    // toolbar toggle conditionally on this capability.
    slides: true
};

// Config tiddler titles read by applyOps. Defaults shipped as plugin
// tiddlers; users can override in the wiki.
var CONFIG_NEW_NODE_STRATEGY = "$:/config/rimir/mindmap/structural/new-node-type-strategy";
var CONFIG_NEW_NODE_TYPE_DEFAULT = "$:/config/rimir/mindmap/structural/new-node-type-default";

// Pick the kn.type for a newly-created node.
// Strategy "fixed:<type>" → always use that type.
// Strategy "derive-from-parent" → read parent tiddler's kn.type; fallback to
//   the configured default; ultimate fallback to "note".
function chooseNewNodeType(wiki, parentTitle) {
    var strategy = trim(wiki.getTiddlerText(CONFIG_NEW_NODE_STRATEGY, "fixed:note"));
    var defaultType = trim(wiki.getTiddlerText(CONFIG_NEW_NODE_TYPE_DEFAULT, "note")) || "note";
    if (strategy.indexOf("fixed:") === 0) {
        return strategy.substring("fixed:".length) || defaultType;
    }
    if (strategy === "derive-from-parent" && parentTitle) {
        var parent = wiki.getTiddler(parentTitle);
        if (parent) {
            var parentType = trim(parent.fields["kn.type"] || "");
            if (parentType) { return parentType; }
        }
    }
    return defaultType;
}

// Return the "root" title for the given args — the title that would be the
// MDOM root with NO focus applied. Used by widget step-out-one to detect
// whether the parent of the current focus is at or above the natural root.
exports.rootTitle = function (args) {
    args = args || {};
    if (args["include-areas-root"] === "yes" || args["include-areas-root"] === true) {
        return null;
    }
    var delimiter = args.delimiter || "/";
    var areaId = trim(args.area || "");
    return areaId ? ("knowledge" + delimiter + areaId) : null;
};

// Used by structural-ops.routeOp to count cascade victims before applying.
exports.titleForOp = function (op) {
    if (!op) { return null; }
    if (op.op === "addNode") {
        // addNode targets the (about-to-be-created) child of `parent`; no
        // pre-existing descendants to cascade.
        return null;
    }
    return titleFromId(op.id);
};

// Inverse of titleForOp / titleFromId: produce the node id for an existing
// tiddler title. Used by presentation-mode click-to-select to translate a
// tiddler title from the playlist into the engine's node-id namespace.
exports.idForTitle = function (title) {
    if (!title) { return null; }
    return "kt:" + title;
};

// Gather the set of direct-child leaf slugs under `parentPath` so we can
// uniquify a fresh slug without colliding. Returns an Object map.
function siblingSlugs(wiki, parentPath, excludeLeaf) {
    if (!parentPath) { return Object.create(null); }
    var filter = "[all[shadows+tiddlers]prefix[" + parentPath + "/]" +
        "removeprefix[" + parentPath + "/]splitbefore[/]]";
    var slugs = wiki.filterTiddlers(filter);
    var set = Object.create(null);
    for (var i = 0; i < slugs.length; i++) {
        var s = slugs[i];
        // splitbefore[/] returns the segment up to and including the slash for
        // intermediate paths, or the full string for leaves. Strip a trailing
        // "/" to normalise.
        if (s.charAt(s.length - 1) === "/") { s = s.substring(0, s.length - 1); }
        if (s && s !== excludeLeaf) { set[s] = true; }
    }
    return set;
}

function renameOrReparent(wiki, oldTitle, newTitle) {
    if (oldTitle === newTitle) { return { changed: false, oldTitle: oldTitle, newTitle: newTitle }; }
    // TW core's wiki.renameTiddler MOVES the tiddler AND calls relinkTiddler
    // internally for tag/list references. flibbles/relink monkey-patches it
    // to also rewrite wikitext refs and pragmas; flibbles/relink-titles adds
    // descendant cascade so `wiki.renameTiddler("a/b", "a/c")` also renames
    // `a/b/x` → `a/c/x`. Single call covers all three layers.
    if (typeof wiki.renameTiddler === "function") {
        if (!wiki.getTiddler(oldTitle)) { return { changed: false, error: "missing source" }; }
        wiki.renameTiddler(oldTitle, newTitle);
    } else {
        // Last-ditch fallback: vanilla TW always has renameTiddler so this is
        // unreachable in practice. Kept for robustness.
        var t = wiki.getTiddler(oldTitle);
        if (!t) { return { changed: false, error: "missing source" }; }
        var fields = Object.create(null);
        for (var k in t.fields) { fields[k] = t.fields[k]; }
        fields.title = newTitle;
        wiki.addTiddler(new $tw.Tiddler(fields));
        wiki.deleteTiddler(oldTitle);
    }
    return { changed: true, oldTitle: oldTitle, newTitle: newTitle };
}

function applyRename(op, wiki, args) {
    var oldTitle = titleFromId(op.id);
    if (!oldTitle) { return { skipped: "no-source-title", op: op }; }
    // Label-field mode: rename only mutates the chosen field. Title (=
    // structural identity) is left alone, so descendants don't cascade and
    // references stay intact. Used when `mm.label-field` is e.g. `caption`.
    var labelField = trim((args && args["label-field"]) || "");
    if (labelField && labelField !== "title") {
        var tiddler = wiki.getTiddler(oldTitle);
        if (!tiddler) { return { skipped: "tiddler-missing", op: op }; }
        var newValue = trim(op.label || "");
        var newFields = {};
        newFields[labelField] = newValue;
        wiki.addTiddler(new $tw.Tiddler(tiddler, newFields, wiki.getModificationFields()));
        return { changed: true, op: op, field: labelField, value: newValue };
    }
    // Title-mode (default): rewrite the leaf segment and cascade.
    var parent = parentTitle(oldTitle);
    if (!parent) { return { skipped: "no-parent-context", op: op }; }
    var slug = sanitizeLib.sanitize(op.label);
    if (!slug) { return { skipped: "empty-slug", op: op }; }
    var siblings = siblingSlugs(wiki, parent, leafSegment(oldTitle));
    var finalSlug = sanitizeLib.uniquify(slug, siblings);
    var newTitle = parent + "/" + finalSlug;
    var result = renameOrReparent(wiki, oldTitle, newTitle);
    result.collisionResolved = (finalSlug !== slug);
    result.wanted = slug;
    result.parent = parent;
    return result;
}

function applyReparent(op, wiki) {
    var oldTitle = titleFromId(op.id);
    var newParent = titleFromId(op.newParent);
    if (!oldTitle) { return { skipped: "no-source-title", op: op }; }
    if (!newParent) { return { skipped: "no-new-parent-title", op: op }; }
    var leaf = leafSegment(oldTitle);
    var currentParent = parentTitle(oldTitle);
    // Identity reparent: source already lives directly under newParent.
    if (currentParent === newParent) { return { changed: false, op: op }; }
    // siblings under newParent — DO NOT exclude `leaf` here: if a different
    // tiddler with the same leaf already lives under newParent (e.g. two
    // distinct `foo`s under different parents), we want uniquify to fire.
    // The source itself isn't in newParent's siblings since its current
    // parent differs (identity case above is the only exception, handled).
    var siblings = siblingSlugs(wiki, newParent, null);
    var finalLeaf = sanitizeLib.uniquify(leaf, siblings);
    var newTitle = newParent + "/" + finalLeaf;
    if (newTitle === oldTitle) { return { changed: false, op: op }; }
    var result = renameOrReparent(wiki, oldTitle, newTitle);
    result.collisionResolved = (finalLeaf !== leaf);
    result.wanted = leaf;
    result.parent = newParent;
    return result;
}

function applyAddNode(op, wiki, args) {
    var parentTitle = titleFromId(op.parent);
    if (!parentTitle) { return { skipped: "no-parent-title", op: op }; }
    var rawLabel = op.node && op.node.label;
    var slug = sanitizeLib.sanitize(rawLabel);
    if (!slug) { return { skipped: "empty-slug", op: op }; }
    var siblings = siblingSlugs(wiki, parentTitle, null);
    var finalSlug = sanitizeLib.uniquify(slug, siblings);
    var newTitle = parentTitle + "/" + finalSlug;
    if (wiki.getTiddler(newTitle)) {
        // Should not happen given uniquify, but defensive: refuse to overwrite.
        return { skipped: "title-already-exists", op: op };
    }
    var knType = chooseNewNodeType(wiki, parentTitle);
    var fields = {
        title: newTitle,
        "kn.type": knType,
        "kn.tier": "fleeting",
        tags: "$:/tags/rimir/knowledge-app/note",
        text: ""
    };
    // Label-field mode: also stash the typed (unsanitized) label on the
    // chosen field so the node's visible name matches what the user typed,
    // not the sanitized title-segment.
    var labelField = trim((args && args["label-field"]) || "");
    if (labelField && labelField !== "title") {
        fields[labelField] = trim(rawLabel || "");
    }
    wiki.addTiddler(new $tw.Tiddler(wiki.getCreationFields(), fields, wiki.getModificationFields()));
    return {
        changed: true,
        op: op,
        newTitle: newTitle,
        knType: knType,
        collisionResolved: (finalSlug !== slug),
        wanted: slug,
        parent: parentTitle
    };
}

function applyRemoveNode(op, wiki) {
    var title = titleFromId(op.id);
    if (!title) { return { skipped: "no-source-title", op: op }; }
    // Enumerate descendants first; relink-titles handles RENAME cascade but
    // not delete cascade, so we walk bottom-up explicitly. Sort by length
    // descending = deepest first.
    var descendants = wiki.filterTiddlers("[all[tiddlers]prefix[" + title + "/]]");
    descendants.sort(function (a, b) { return b.length - a.length; });
    for (var i = 0; i < descendants.length; i++) {
        wiki.deleteTiddler(descendants[i]);
    }
    wiki.deleteTiddler(title);
    return { changed: true, deleted: descendants.length + 1, op: op };
}

exports.applyOps = function (ops, args, wiki) {
    if (!ops || !ops.length) { return []; }
    var results = [];
    for (var i = 0; i < ops.length; i++) {
        var op = ops[i];
        try {
            switch (op.op) {
                case "rename":     results.push(applyRename(op, wiki, args)); break;
                case "reparent":   results.push(applyReparent(op, wiki)); break;
                case "removeNode": results.push(applyRemoveNode(op, wiki)); break;
                case "addNode":    results.push(applyAddNode(op, wiki, args)); break;
                default: results.push({ skipped: "unsupported-op", op: op });
            }
        } catch (e) {
            console.error("[knowledge-tree.applyOps]", op, e);
            results.push({ error: e.message || String(e), op: op });
        }
    }
    return results;
};

// Exposed for tests.
exports._titleFromId = titleFromId;
exports._parentTitle = parentTitle;
exports._leafSegment = leafSegment;
exports._siblingSlugs = siblingSlugs;

exports.refreshFilter = function (args) {
    args = args || {};
    var delimiter = args.delimiter || "/";
    if (args["include-areas-root"] === "yes" || args["include-areas-root"] === true) {
        // Any tiddler under knowledge/<area>/ AND area-tagged tiddlers.
        // Slide tiddlers excluded — they don't affect tree shape, only the
        // owner's mm.slide-order field (which lives ON the owner and is
        // already covered). Watching them would trigger wasteful reproduces
        // on every slide-body keystroke.
        return "[all[shadows+tiddlers]prefix[knowledge" + delimiter + "]!tag[" + SLIDE_TAG + "]] [all[shadows+tiddlers]tag[" + AREA_TAG + "]] [[" + TYPES_TIDDLER + "]]";
    }
    var areaId = trim(args.area || "");
    if (!areaId) { return null; }
    var areaPrefix = "knowledge" + delimiter + areaId;
    var focusTitle = trim(args["focus-title"] || "");
    if (focusTitle && (focusTitle === areaPrefix || focusTitle.indexOf(areaPrefix + delimiter) === 0)) {
        return "[all[shadows+tiddlers]prefix[" + focusTitle + delimiter + "]!tag[" + SLIDE_TAG + "]] [[" + focusTitle + "]] [[" + TYPES_TIDDLER + "]]";
    }
    return "[all[shadows+tiddlers]prefix[" + areaPrefix + delimiter + "]!tag[" + SLIDE_TAG + "]] [[" + TYPES_TIDDLER + "]]";
};
","type":"application/javascript","module-type":"mindmap-producer"},"$:/plugins/rimir/mindmap/producers":{"title":"$:/plugins/rimir/mindmap/producers","type":"text/vnd.tiddlywiki","text":"! Producers

A ''producer'' is a `module-type: mindmap-producer` JS module that turns wiki data into a base MDOM document. Built-in producers cover the common cases; custom producers can be added in any plugin that registers a module of this type.

!! Built-in producers

!!! filter-tree

Title-path segmentation of any filter result.

|!Argument |!Default |!Purpose |
|`filter` |(required) |TW filter expression returning titles to include |
|`delimiter` |`/` |Path separator used for tree segmentation |
|`root-label` |`Mindmap` |Label for the synthetic root |
|`body-field` |`text` |Tiddler field shown as MDOM node body |

Used implicitly by the `<$mindmap filter="..."/>` quick form. Node IDs are prefixed `ft:`.

!!! knowledge-tree

Renders a `rimir/knowledge-app` area as a mindmap. Enriches nodes with type icons (from `kn.type`) and area colour.

|!Argument |!Default |!Purpose |
|`area` |(required) |Area id (e.g. `llm`, `health`) |
|`delimiter` |`/` |Path separator |
|`include-areas-root` |`no` |If `yes`, renders a forest of all areas (ignores `area`) |

Node IDs are prefixed `kt:`.

!!! json

Reads MDOM verbatim from a tiddler's text field.

|!Argument |!Default |!Purpose |
|`tiddler` |(required) |Title of a tiddler whose text is valid MDOM JSON |

!! Installed producers (all sources)

<$list filter="[mindmap-producers[]]">
* <<currentTiddler>>
</$list>

!! Writing a custom producer

Create a JS module with header:

```
title: $:/your-plugin/producers/my-producer.js
type: application/javascript
module-type: mindmap-producer
```

Export the following:

```
exports.name = "my-producer";
exports.produce = function (args, wiki) {
    return {
        version: 1,
        root: { id: "mine:root", label: "...", children: [...] },
        meta: { producer: "my-producer", producedAt: Date.now() }
    };
};
exports.refreshFilter = function (args) {
    return "[your-filter-here]";   // optional; widget re-projects when matching tiddlers change
};
exports.describe = function () {
    return { name: "my-producer", args: [...] };
};
```

Node IDs SHOULD be stable across renders and prefixed with a namespace unique to your producer.
"},"$:/plugins/rimir/mindmap/readme":{"title":"$:/plugins/rimir/mindmap/readme","type":"text/vnd.tiddlywiki","text":"! mindmap

Engine-agnostic mindmap rendering for TiddlyWiki. Provides a canonical mindmap document model (MDOM), a per-view overlay layer for layout/restructuring that does not write back to wiki data, and a pluggable adapter contract for visualization libraries.

!! Key features

* ''Engine-agnostic'' — pluggable adapters via `module-type: mindmapengine`. Ships with no built-in engine; install a companion plugin such as `rimir/mindmap-elixir` to render.
* ''Three producer mechanisms'' — `module-type: mindmap-producer` modules, JSON MDOM tiddlers, or a `filter=` quick form. All feed the same canonical document.
* ''Base + overlay model'' — view-specific positioning, hides, reparenting and custom nodes ride in a separate overlay tiddler (ordered op log). Multiple views over the same base data are first-class.
* ''Structural editing (write-back)'' — producers that declare `capabilities.structural` translate drag-rename / drag-reparent / addNode / removeNode into real wiki mutations (`renameTiddler` cascades references via flibbles/relink; `addTiddler`/`deleteTiddler` for create/destroy). Cascade-confirm modal guards large operations. Focus mode drills into subtrees.
* ''Stable IDs with rename rescue'' — producers assign deterministic IDs; orphaned overlay ops survive upstream renames and surface a manual prune action rather than silently disappearing.
* ''Forward-compatible with slide mode'' — the overlay op vocabulary doubles as the slide-ops vocabulary for the planned presentation player.

!! Prerequisites

* TiddlyWiki 5.3.0+
* At least one installed engine plugin (e.g. `$:/plugins/rimir/mindmap-elixir`).

!! Quick start

# Install this plugin alongside an engine plugin.
# Create a view tiddler with fields `mm.producer`, `mm.args`, `mm.engine`, `mm.overlay`.
# Render with `<$mindmap view="MyView"/>`.

For a one-off mindmap of any filter:

```
<$mindmap filter="[tag[Knowledge]]" engine="MindElixir" overlay="MyMap/overlay"/>
```
"},"$:/plugins/rimir/mindmap/settings":{"title":"$:/plugins/rimir/mindmap/settings","type":"text/vnd.tiddlywiki","text":"! Settings

!! Default engine

When a `$mindmap` widget does not specify `engine=` and the view tiddler does not set `mm.engine`, the widget falls back to this config tiddler. If empty, the first registered `mindmapengine` module is used.

|!Tiddler |`$:/config/rimir/mindmap/default-engine` |
|!Value |Engine name (e.g. `MindElixir`) |

''Current value:''
<$edit-text tiddler="$:/config/rimir/mindmap/default-engine" tag="input" default="" placeholder="(first registered engine)"/>

!! Engine selection precedence

# Widget attribute: `<$mindmap engine="..."/>`
# View tiddler field: `mm.engine`
# Config tiddler above
# First registered `mindmapengine` module

!! Installed engines

<$list filter="[mindmap-engines[]]" emptyMessage="''No engines installed.'' Install a companion plugin such as `rimir/mindmap-elixir`.">
* <<currentTiddler>>
</$list>

!! Installed producers

<$list filter="[mindmap-producers[]]" emptyMessage="(none — should not happen if this plugin is loaded)">
* <<currentTiddler>>
</$list>

!! Structural editing (write-back to real tiddlers)

When the active producer declares `capabilities.structural: true` (e.g. `knowledge-tree`), drag-reparent / rename / +child / Delete in the mindmap mutate the underlying tiddlers directly. The two settings below tune that behaviour.

!!! Default type for new nodes

When the user creates a node via Tab/Enter, the new tiddler's `kn.type` field is chosen by this strategy:

* `fixed:<type>` — always use the literal type (e.g. `fixed:note`, `fixed:idea`).
* `derive-from-parent` — read the parent node's `kn.type`. Falls back to the default below when the parent has none.

|!Tiddler |`$:/config/rimir/mindmap/structural/new-node-type-strategy` |
|!Default |`fixed:note` |

''Current value:''
<$edit-text tiddler="$:/config/rimir/mindmap/structural/new-node-type-strategy" tag="input" default="fixed:note" placeholder="fixed:note"/>

Quick presets:

* <$button class="rr-link-btn"><$action-setfield $tiddler="$:/config/rimir/mindmap/structural/new-node-type-strategy" text="fixed:note"/>fixed:note</$button>
* <$button class="rr-link-btn"><$action-setfield $tiddler="$:/config/rimir/mindmap/structural/new-node-type-strategy" text="fixed:idea"/>fixed:idea</$button>
* <$button class="rr-link-btn"><$action-setfield $tiddler="$:/config/rimir/mindmap/structural/new-node-type-strategy" text="derive-from-parent"/>derive-from-parent</$button>

!!! Cascade-confirm threshold

Reparent / delete / rename operations whose effect spans more than this many descendant tiddlers pop a confirm modal before applying. Set to a very high number to disable the confirmation entirely.

|!Tiddler |`$:/config/rimir/mindmap/structural/cascade-threshold` |
|!Default |`10` |

''Current value:''
<$edit-text tiddler="$:/config/rimir/mindmap/structural/cascade-threshold" tag="input" type="number" default="10"/>

!!! Visible-label field

The bottom-right actions panel includes a small dropdown that picks the tiddler field used as the visible node label. Picking `title` keeps the current behaviour: node names follow the leaf-segment of the title (drag-rename renames the tiddler, references cascade via `flibbles/relink-titles`). Picking any other field — typically `caption` — decouples //display// from //structural identity//:

* drag-rename writes the typed value to the chosen field; the title is preserved (no cascade).
* `+child` / `+sibling` still derives a sanitized title slug from the typed value, AND stamps the typed value on the chosen field of the new tiddler.
* reparent still cascades structurally (titles change, references update) — only the label source is decoupled.
* empty field on the source tiddler falls back to the leaf segment (`caption` mode, marked `mm:label-derived`) or to the literal `UNDEFINED` (any other field, marked `mm:label-status`).

The list of pickable fields is taken from this config tiddler, one field per line:

|!Tiddler |`$:/config/rimir/mindmap/label-fields` |
|!Default |`title`<br/>`caption` |

''Current value:''
<$edit-text tiddler="$:/config/rimir/mindmap/label-fields" tag="textarea" default={{{ [[title]] +[addsuffix[\n]addsuffix[caption]] }}} placeholder="title&#10;caption&#10;kn.caption"/>

The choice is stored in `$:/state/rimir/mindmap/<key>/label-field` (session-scoped — lost on reload). A view tiddler can set `mm.label-field` for a stable per-view default.

!! Slides-only view (canvas toolbar)

When the active producer supports it (`knowledge-tree` does; `capabilities.slides: true`), the canvas toolbar carries a ''Slides only'' toggle. Pressed = the tree is pruned to nodes that have at least one slide, plus any ancestor needed to keep them connected to the root. Released = the full tree returns.

The choice lives in `$:/state/rimir/mindmap/<key>/slides-only` — `$:/state/`, so it doesn't sync and doesn't persist across reloads. Slides-only is a transient view mode; if you want a durable "this view always shows slides only" preference, file an issue and we'll add it.

Composes with focus mode and label-field — focus re-roots first, then slides-only prunes the focused subtree, then label-field rewrites the visible labels.

!! Slide authoring (right pane)

The preview pane carries a modebar above its content with the selected tiddler's title on the left and a unified dropdown on the right — ''Body'' / ''Slides'' / ''<each presentation>'' / ''+ New presentation…''. Switching to ''Slides'' replaces the body preview with a list of slide cards for the selected node — add, edit (inline), move up/down, delete.

Each slide is its own tiddler at `<owner>/slides/<slug>`:

|!Field |!Value |
|`kn.type` |`slide` |
|tags |`$:/tags/rimir/mindmap/slide` |
|`mm.slide-of` |Owner tiddler title (back-reference; relink-titles cascades on owner-rename) |
|`mm.slide-layout` |`default` / `title` / `bullets` / any custom CSS class |
|`mm.slide-notes` |Single-line presenter notes |
|caption |Optional display name shown in the slide list |
|text |Slide body — plain wikitext |

The owner tiddler's `mm.slide-order` TW list field carries the slides in display / playback order. When the owner is renamed via the structural editing flow, `flibbles/relink-titles` automatically renames the whole `<owner>/slides/<*>` subtree, so the slide references in `mm.slide-order` survive the rename without manual fix-up.

''Recognised layouts:''

* `default` — full-bleed wikitext content (no extra style).
* `title` — centred large heading (CSS class `rr-mindmap-slide-content-title`).
* `bullets` — tighter bullet list styling (CSS class `rr-mindmap-slide-content-bullets`).
* Any custom value — used verbatim as a CSS class (`rr-mindmap-slide-content-<value>`); style it yourself.

''+ Add slide:''

Clicking ''+ Add slide'' creates a blank slide tiddler under the selected node (the `rr-mindmap-add-slide` widget message handles the creation + slug uniquification) and opens it inline in edit mode — type the caption / pick a layout / write the body, and every keystroke writes through (no Save button; ''Done'' just collapses the editor back to view mode).

''Slide exclusion:''

The `knowledge-tree` producer skips slide-tagged tiddlers (both in the produced MDOM and the watched-titles filter). Slides are content owned by their parent node, not structural nodes in the tree.

''Session state:''

* `$:/state/rimir/mindmap/<key>/inspect-mode` — Body / Slides / Presentation
* `$:/state/rimir/mindmap/<key>/slide-editing` — title of the slide currently in edit mode (empty = list view)

Both are `$:/state/` titles, so they don't sync.

!! Named presentations (Phase 2)

A ''presentation'' is a playlist: an ordered list of tiddler titles whose slides will be walked in sequence during playback. Presentations live as their own tiddlers, decoupled from any one view-level overlay — multiple presentations can target the same view, and the same node can appear in multiple presentations.

A presentation tiddler:

* is tagged `$:/tags/rimir/mindmap/presentation`
* has field `mm.view` — the view tiddler this presentation belongs to
* has field `mm.slides-order` — TW list of tiddler titles
* may have fields `mm.transition` and `mm.duration` for the (still planned) player

The currently-active presentation for a view is referenced by the view tiddler's `mm.presentation` field — a regular tiddler field, so the choice survives reloads.

''Authoring flow:''

# The preview-pane modebar dropdown (above the right pane) unifies mode and presentation choice. Options: ''Body'', ''Slides'', and under a ''Presentations'' optgroup each existing presentation for this view plus ''+ New presentation…''.
# Picking ''+ New presentation…'' prompts for a name, sanitises a slug under `presentations/<slug>`, creates the tiddler with the right tags and fields, sets it active on the view, and switches inspect-mode to "presentation".
# Picking an existing presentation atomically activates it (`mm.presentation`) AND switches to "presentation" mode. Picking Body/Slides switches mode without disturbing the active presentation.
# With a presentation active, selecting a node in the canvas reveals a ''+ Add / − Remove'' button in the bottom-right actions panel — toggles the selected tiddler's title in `mm.slides-order`.
# In Presentation mode the right pane shows the playlist: each member node's title (clickable — focuses it on the canvas) plus its slide tiddlers (via `[<nodeTitle>mm-slides[]]`), rendered live with their layout class.

''Lifecycle:''

* Presentations coexist — picking `[none]` deactivates without deleting. Switching presentations is non-destructive.
* Deleting a presentation tiddler removes it from the toolbar dropdown automatically (the widget watches presentation-tagged tiddlers).
* Renaming a tiddler in `mm.slides-order` does NOT cascade — Phase 3 will register the field with flibbles/relink for rename cascade.

Phase 3 will add the ''presentation creation mode'' (visual fading of non-included nodes on the canvas, drag-to-reorder, per-slide transition overrides) and the ''fullscreen player'' (sequential walk with keyboard navigation).

!! Overlay tiddler titles and persistence

Drag/rename/collapse changes are stored in the overlay tiddler named by the view's `mm.overlay` field (or the `overlay=` widget attribute). For changes to survive browser reloads and server restarts, that title MUST be //synced to the server// — that is, it MUST match the wiki's `$:/config/SyncFilter`.

The TiddlyWiki core default excludes anything under `$:/state/`, `$:/temp/`, `$:/status/` and `$:/HistoryList`. So:

* `Mindmap/<view>/overlay` — //persists// (regular tiddler, written to disk)
* `$:/config/rimir/mindmap/overlays/<view>` — //persists// (system but synced)
* `$:/state/...` — ''lost on reload''. Only use this for ephemeral session state.

If your wiki has a custom `$:/config/SyncFilter`, mirror that here when naming overlays.

!! Overlay write debounce

Overlay tiddler writes are debounced at 250 ms to avoid spamming filesystem-watcher and git-int with every intermediate drag event. This is currently hard-coded; if you need to tune it, file an issue.

!! Restricted-wiki environments

If `llm-connect` or another plugin restricts which tiddlers may be written, overlay tiddler titles MUST be in the protection allow filter or writes will be silently dropped. The widget reflects this with no error — drag changes appear to work in the UI but do not persist after reload.
"},"$:/plugins/rimir/mindmap/structural-ops.js":{"title":"$:/plugins/rimir/mindmap/structural-ops.js","text":"/*\
title: $:/plugins/rimir/mindmap/structural-ops.js
type: application/javascript
module-type: library

Central per-op router for the $mindmap widget. Decides whether a user-emitted
Op should mutate real wiki tiddlers via `producer.applyOps` (structural path)
or be appended to the per-view overlay tiddler (visual-only path).

Routing is per-op, NOT per-producer:
- A producer declares `capabilities.structural: true` and a whitelist
  `capabilities.structuralOps: ["rename", "reparent", "addNode", "removeNode"]`.
- An op whose `op` field is in that whitelist runs through `producer.applyOps`.
- Anything else (notably `setAttr` and `reorder`) goes to the overlay store.
- Producers without `structural: true` route every op to overlay (v1 behaviour
  for `json`, `filter-tree`).

Cascade-confirm threshold checking (Landing C) lives here too — `routeOp`
counts affected tiddlers and returns "deferred" when over threshold so the
widget can pop a confirm modal before applying.

\*/

"use strict";

var DEFAULT_CASCADE_THRESHOLD = 10;

// Set of op kinds that NEVER mutate source data, only canvas chrome.
var OVERLAY_ONLY_OPS = Object.create(null);
["setAttr", "hide", "reorder"].forEach(function (k) { OVERLAY_ONLY_OPS[k] = true; });

function getStructuralWhitelist(producer) {
    var caps = producer && producer.capabilities;
    if (!caps || !caps.structural) { return null; }
    var ops = caps.structuralOps;
    if (!ops || !ops.length) { return null; }
    var set = Object.create(null);
    for (var i = 0; i < ops.length; i++) { set[ops[i]] = true; }
    return set;
}

// Count how many descendant tiddlers a rename/reparent/removeNode op would
// affect. Producers expose a per-op "title resolver" so the router can ask
// the wiki "what title would this op operate on?" without knowing the
// producer's id encoding.
function countAffectedDescendants(op, producer, wiki) {
    if (!producer || typeof producer.titleForOp !== "function") { return 0; }
    var title = null;
    try { title = producer.titleForOp(op); } catch (e) { return 0; }
    if (!title) { return 0; }
    // descendants only; the op's own tiddler isn't counted as a cascade target.
    var results = wiki.filterTiddlers("[all[tiddlers+shadows]prefix[" + title + "/]]");
    return results.length;
}

/*
 * routeOp — return { mode, reason?, count? }
 *
 *   mode === "structural" → caller invokes producer.applyOps([op], args, wiki)
 *   mode === "overlay"    → caller invokes store.append(op)
 *   mode === "deferred"   → caller stores op in pending-state + pops confirm modal
 *   mode === "drop"       → caller silently discards (e.g., op for unknown id)
 */
exports.routeOp = function (op, producer, options) {
    if (!op || !op.op) { return { mode: "drop", reason: "invalid op" }; }
    options = options || {};
    var threshold = typeof options.cascadeThreshold === "number" ?
        options.cascadeThreshold : DEFAULT_CASCADE_THRESHOLD;
    var wiki = options.wiki;

    var structural = getStructuralWhitelist(producer);
    var isStructuralOp = structural && structural[op.op];

    if (!isStructuralOp) {
        // setAttr/reorder/hide always live in overlay.
        // Unknown ops also fall through to overlay so unknown-namespace attrs
        // round-trip without loss.
        return { mode: "overlay" };
    }

    // Structural path. For ops with cascade potential, gate on threshold.
    // Rename in non-title label-field mode is a single-field write — no
    // cascade, no descendants touched — so the threshold check is skipped.
    var labelField = options.args && options.args["label-field"];
    var renameTouchesTitleOnly = (op.op === "rename" && labelField && labelField !== "title");
    if (wiki && !renameTouchesTitleOnly &&
            (op.op === "rename" || op.op === "reparent" || op.op === "removeNode")) {
        var n = countAffectedDescendants(op, producer, wiki);
        if (n > threshold) {
            return { mode: "deferred", reason: "cascade-threshold", count: n };
        }
    }
    return { mode: "structural" };
};

exports.OVERLAY_ONLY_OPS = OVERLAY_ONLY_OPS;
exports.DEFAULT_CASCADE_THRESHOLD = DEFAULT_CASCADE_THRESHOLD;
exports._getStructuralWhitelist = getStructuralWhitelist;     // exposed for tests
exports._countAffectedDescendants = countAffectedDescendants; // exposed for tests
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/mindmap/styles":{"title":"$:/plugins/rimir/mindmap/styles","tags":"$:/tags/Stylesheet","type":"text/vnd.tiddlywiki","text":"/* Container for the $mindmap widget. Engines render into a child div with
   class .rr-mindmap-canvas; the canvas needs a definite height to render. */
.rr-mindmap {
    position: relative;
    width: 100%;
    min-height: 240px;
    display: flex;
    flex-direction: column;
}

/* Warning wash applied when a structural view is in title-label mode —
   drag-rename + drag-reparent mutate filesystem titles (and cascade refs
   via flibbles/relink). Switching the label-field dropdown to caption or
   any other field clears the wash. The canvas tint can't paint over mind-
   elixir's own background, so we frame it instead with a red inset shadow
   that's clearly visible above the engine's drawing. */
.rr-mindmap-title-active {
    background-color: #fff0f0;
}
.rr-mindmap-title-active .rr-mindmap-canvas {
    box-shadow: inset 0 0 0 3px #f88;
}
.rr-mindmap-title-active .rr-mindmap-toolbar {
    background-color: #fee;
    border-top: 3px solid #f88;
    border-bottom: 1px solid #f88;
}
/* Preview pane keeps a neutral background — it's a tiddler-editor surface,
   not the destructive canvas. Override the container's red wash. */
.rr-mindmap-title-active .rr-mindmap-preview {
    background-color: <<colour tiddler-background>>;
}

.rr-mindmap-title-warning {
    display: none;
    margin-left: 0.6em;
    color: #a00;
    font-weight: bold;
    flex: 1 1 auto;
}
.rr-mindmap-title-active .rr-mindmap-title-warning {
    display: inline;
}

/* Horizontal layout under the toolbar: canvas on the left, preview pane
   (when a node is selected) on the right. */
.rr-mindmap-main {
    flex: 1 1 auto;
    display: flex;
    flex-direction: row;
    min-height: 0;
}

.rr-mindmap-canvas {
    flex: 1 1 auto;
    height: 100%;
    min-height: 0;
    min-width: 0;
    position: relative;
}

.rr-mindmap-preview {
    flex: 0 0 35%;
    max-width: 35%;
    height: 100%;
    overflow: auto;
    padding: 12px 16px;
    border-left: 1px solid var(--theme-tiddler-border, #e0e0e0);
    background: var(--theme-tiddler-background, transparent);
    font-size: 0.95em;
}
.rr-mindmap-preview-header {
    font-family: var(--theme-monospace-font, monospace);
    font-size: 0.8em;
    opacity: 0.7;
    margin-bottom: 8px;
    word-break: break-all;
}
/* Modebar at the top of the preview pane: selected-tiddler title on the left,
   inspect-mode dropdown (Body / Slides) on the right. The dropdown lives here
   — not over the canvas — because it controls what the preview shows. */
.rr-mindmap-preview-modebar {
    display: flex;
    align-items: center;
    gap: 0.6em;
    padding-bottom: 8px;
    margin-bottom: 10px;
    border-bottom: 1px solid <<colour tiddler-border>>;
}
.rr-mindmap-preview-modebar-title {
    flex: 1 1 auto;
    font-family: var(--theme-monospace-font, monospace);
    font-size: 0.8em;
    opacity: 0.7;
    word-break: break-all;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.rr-mindmap-preview-modebar .rr-mindmap-modebar-select {
    flex: 0 0 auto;
}
.rr-mindmap-preview-body {
    line-height: 1.5;
}
.rr-mindmap-preview-body .rr-text-view-editable {
    cursor: text;
}
.rr-mindmap-preview-edit {
    display: flex;
    flex-direction: column;
}
.rr-mindmap-preview-edit .tc-edit-texteditor {
    min-height: 220px;
    width: 100%;
}

.rr-mindmap-toolbar {
    display: flex;
    align-items: center;
    gap: 0.4em;
    padding: 0.25em 0.4em;
    font-size: 0.85em;
    border-bottom: 1px solid var(--theme-tiddler-border, #e0e0e0);
    background: var(--theme-tiddler-background, transparent);
}

.rr-mindmap-toolbar .rr-mindmap-engine,
.rr-mindmap-toolbar .rr-mindmap-producer {
    opacity: 0.65;
    font-family: var(--theme-monospace-font, monospace);
}

/* Slides-only filter toggle button. Compact chip styled to fit alongside
   the monospace producer/engine labels; flips to a pressed accent when
   active, mirroring the canvas pruning. */
.rr-mindmap-slides-only-btn {
    background: transparent;
    border: 1px solid <<colour tiddler-border>>;
    border-radius: 3px;
    padding: 1px 8px;
    font: inherit;
    font-size: 0.85em;
    cursor: pointer;
    color: inherit;
}
.rr-mindmap-slides-only-btn:hover {
    background: <<colour message-background>>;
}
.rr-mindmap-slides-only-btn-active {
    background: <<colour primary>>;
    color: <<colour background>>;
    border-color: <<colour primary>>;
}
.rr-mindmap-slides-only-btn-active:hover {
    background: <<colour primary>>;
    color: <<colour background>>;
    opacity: 0.9;
}

/* Cascade-confirm modal. Self-contained: defines its own page-darkening +
   centering layer (does NOT rely on kn-modal-overlay cascade) so a missing
   knowledge-app stylesheet or a CSS load-order race can't leave the card
   underneath the dim wash. */
.rr-mindmap-cascade-overlay {
    position: fixed;
    inset: 0;
    z-index: 9001;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    isolation: isolate;
}
.rr-mindmap-cascade-modal {
    position: relative;
    z-index: 1;
    max-width: 460px;
    width: 90vw;
    background: <<colour tiddler-background>>;
    color: <<colour foreground>>;
    border-radius: 6px;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
    overflow: hidden;
}
.rr-mindmap-cascade-modal-header {
    padding: 12px 16px;
    border-bottom: 1px solid <<colour tiddler-border>>;
    background: <<colour message-background>>;
}
.rr-mindmap-cascade-modal-body {
    padding: 16px;
    line-height: 1.5;
}
.rr-mindmap-cascade-modal-body > div {
    margin-bottom: 0.6em;
}
.rr-mindmap-cascade-modal-body > div:last-child {
    margin-bottom: 0;
}
.rr-mindmap-cascade-modal-hint {
    font-size: 0.85em;
    opacity: 0.7;
}
.rr-mindmap-cascade-modal-actions {
    padding: 12px 16px;
    border-top: 1px solid <<colour tiddler-border>>;
    display: flex;
    gap: 12px;
    justify-content: flex-end;
}

/* Floating bottom-right action panel — matches the visual style of
   mind-elixir's own built-in toolbars (.mind-elixir-toolbar.rb). We add it
   above mind-elixir's bottom-right zoom panel so the two stack vertically. */
.rr-mindmap-actions {
    position: absolute;
    right: 20px;
    bottom: 80px;
    z-index: 50;
    display: flex;
    gap: 8px;
    padding: 8px;
    background: var(--theme-tiddler-background, #fff);
    color: var(--theme-foreground, #333);
    border-radius: 5px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.rr-mindmap-edit-btn {
    min-width: 28px;
    height: 24px;
    padding: 0 0.5em;
    font-size: 1.1em;
    line-height: 1;
    border: 1px solid var(--theme-tiddler-border, #d0d0d0);
    background: var(--theme-tiddler-background, transparent);
    color: inherit;
    border-radius: 3px;
    cursor: pointer;
}
.rr-mindmap-edit-btn:hover:not(:disabled) {
    background: var(--theme-foreground, #000);
    color: var(--theme-background, #fff);
}
.rr-mindmap-edit-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.rr-mindmap-label-field-select {
    height: 24px;
    padding: 0 4px;
    font-size: 0.85em;
    line-height: 1;
    border: 1px solid <<colour tiddler-border>>;
    background: <<colour tiddler-background>>;
    color: inherit;
    border-radius: 3px;
    cursor: pointer;
}

/* Slide pane — replaces the body preview when the inspect-mode dropdown is
   set to "slides". Renders a list of slide cards with view/edit affordances. */
.rr-mindmap-slide-pane {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.rr-mindmap-slide-pane-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 0.6em;
    padding-bottom: 6px;
    border-bottom: 1px solid <<colour tiddler-border>>;
}
.rr-mindmap-slide-pane-header strong {
    word-break: break-all;
}
.rr-mindmap-slide-count {
