.rr-mindmap-slide-caption {
    font-weight: 600;
    flex: 1 1 auto;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.rr-mindmap-slide-edit-form {
    display: flex;
