title: $:/plugins/rimir/mindmap/test/test-presentation-filter.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Unit tests for the `mm-presentations` filter operator.

\*/

"use strict";

describe("mindmap-presentations-filter", function () {
    var op = require("$:/plugins/rimir/mindmap/filters/presentation.js")["mm-presentations"];

    function setupWiki(tiddlers) {
        var wiki = new $tw.Wiki();
        wiki.addTiddlers(tiddlers || []);
        return wiki;
    }

    function runOp(wiki, viewTitle) {
        // Filter ops ignore the input list — pass an empty no-op source.
        var source = function () { /* no inputs */ };
        return op(source, { operand: viewTitle }, { wiki: wiki });
    }

    it("returns presentations tagged for the given view", function () {
        var wiki = setupWiki([
            { title: "views/main", text: "" },
            { title: "presentations/intro",
              tags: "$:/tags/rimir/mindmap/presentation",
              "mm.view": "views/main",
              "mm.slides-order": "" },
            { title: "presentations/deep-dive",
              tags: "$:/tags/rimir/mindmap/presentation",
              "mm.view": "views/main",
              "mm.slides-order": "" }
        ]);
        var out = runOp(wiki, "views/main");
        expect(out).toEqual(["presentations/deep-dive", "presentations/intro"]);
    });

    it("excludes presentations belonging to other views", function () {
        var wiki = setupWiki([
            { title: "views/a", text: "" },
            { title: "views/b", text: "" },
            { title: "p1", tags: "$:/tags/rimir/mindmap/presentation", "mm.view": "views/a" },
            { title: "p2", tags: "$:/tags/rimir/mindmap/presentation", "mm.view": "views/b" }
        ]);
        expect(runOp(wiki, "views/a")).toEqual(["p1"]);
        expect(runOp(wiki, "views/b")).toEqual(["p2"]);
    });

    it("excludes tiddlers without the presentation tag", function () {
        var wiki = setupWiki([
            { title: "presentations/wannabe",
              "mm.view": "views/main",
              "mm.slides-order": "" }
        ]);
        expect(runOp(wiki, "views/main")).toEqual([]);
    });

    it("returns empty list for blank view title", function () {
        var wiki = setupWiki([
            { title: "p1", tags: "$:/tags/rimir/mindmap/presentation", "mm.view": "views/main" }
        ]);
        expect(runOp(wiki, "")).toEqual([]);
    });

    it("ignores whitespace around the mm.view value", function () {
        var wiki = setupWiki([
            { title: "p1",
              tags: "$:/tags/rimir/mindmap/presentation",
              "mm.view": "  views/main  " }
        ]);
        expect(runOp(wiki, "views/main")).toEqual(["p1"]);
    });
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/mindmap/test/test-preview-visibility.js":{"title":"$:/plugins/rimir/mindmap/test/test-preview-visibility.js","text":"/*\
title: $:/plugins/rimir/mindmap/test/test-preview-visibility.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Regression pins for `_isPreviewPaneVisible` (extracted from
`updatePreviewPaneVisibility`).

The rule is mode-aware: Body / Slides need a selection; Presentation needs
an active presentation (selection optional). The v0.2.6 implementation
kept the pane open whenever a presentation was active on the view, which
blocked the canvas from reclaiming full width when the user deselected in
Body / Slides mode. v0.2.9 fixed that — these specs make sure the rule
doesn't regress.

\*/

"use strict";

describe("mindmap-preview-visibility", function () {
    var widget = require("$:/plugins/rimir/mindmap/widget.js");
    var fn = widget._isPreviewPaneVisible;

    describe("body mode", function () {
        it("visible iff there is a selection (presentation existence ignored)", function () {
            expect(fn("body", true,  false)).toBe(true);
            expect(fn("body", true,  true)).toBe(true);
            expect(fn("body", false, false)).toBe(false);
            // The regression: presentation active but no selection → still
            // hidden. The v0.2.6 logic returned true here.
            expect(fn("body", false, true)).toBe(false);
        });
    });

    describe("slides mode", function () {
        it("visible iff there is a selection (presentation existence ignored)", function () {
            expect(fn("slides", true,  false)).toBe(true);
            expect(fn("slides", true,  true)).toBe(true);
            expect(fn("slides", false, false)).toBe(false);
            // Same regression check as body mode.
            expect(fn("slides", false, true)).toBe(false);
        });
    });

    describe("presentation mode", function () {
        it("visible iff there is an active presentation (selection optional)", function () {
            expect(fn("presentation", false, true)).toBe(true);
            expect(fn("presentation", true,  true)).toBe(true);
            expect(fn("presentation", false, false)).toBe(false);
            // No selection AND no presentation → nothing to render.
            expect(fn("presentation", true,  false)).toBe(false);
        });
    });

    describe("unknown / falsy mode (defensive)", function () {
        it("treats unknown modes as body (selection-gated)", function () {
            // The current implementation: if mode !== "presentation",
            // visibility follows hasSelection. This means a stale state
            // tiddler with garbage in it doesn't accidentally pin the pane
            // open — it falls into the selection-gated branch.
            expect(fn("garbage", true,  false)).toBe(true);
            expect(fn("garbage", false, true)).toBe(false);
            expect(fn("",        false, true)).toBe(false);
            expect(fn(undefined, false, true)).toBe(false);
        });
    });
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/mindmap/test/test-sanitize-title.js":{"title":"$:/plugins/rimir/mindmap/test/test-sanitize-title.js","text":"/*\
title: $:/plugins/rimir/mindmap/test/test-sanitize-title.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Unit tests for lib/sanitize-title.js.

\*/

"use strict";

describe("mindmap-sanitize-title", function () {
    var lib = require("$:/plugins/rimir/mindmap/lib/sanitize-title.js");
    var sanitize = lib.sanitize;
    var uniquify = lib.uniquify;

    describe("sanitize", function () {
        it("lowercases and collapses whitespace", function () {
            expect(sanitize("API Endpoints")).toBe("api-endpoints");
            expect(sanitize("  spaced   out  ")).toBe("spaced-out");
            expect(sanitize("\ttab\nnewline")).toBe("tab-newline");
        });

        it("strips path-hostile characters", function () {
            expect(sanitize("a/b\\c|d")).toBe("abcd");
            expect(sanitize("[brackets]")).toBe("brackets");
            expect(sanitize("{braces}")).toBe("braces");
            expect(sanitize("<angles>")).toBe("angles");
            expect(sanitize("#hash?question\"quote'apost"))
                .toBe("hashquestionquoteapost");
        });

        it("collapses multiple hyphens and trims them", function () {
            expect(sanitize("--leading---internal--trailing--"))
                .toBe("leading-internal-trailing");
            expect(sanitize("a  --  b")).toBe("a-b");
        });

        it("returns null when nothing usable remains", function () {
            expect(sanitize("")).toBe(null);
            expect(sanitize("   ")).toBe(null);
            expect(sanitize("---")).toBe(null);
            expect(sanitize("///\\\\\\")).toBe(null);
            expect(sanitize(null)).toBe(null);
            expect(sanitize(undefined)).toBe(null);
        });

        it("preserves unicode letters and digits", function () {
            expect(sanitize("über Cool 42")).toBe("über-cool-42");
            expect(sanitize("café-au-lait")).toBe("café-au-lait");
        });

        it("coerces non-string input", function () {
            expect(sanitize(42)).toBe("42");
        });
    });

    describe("uniquify", function () {
        it("returns slug unchanged when not taken", function () {
            expect(uniquify("foo", new Set(["bar"]))).toBe("foo");
            expect(uniquify("foo", [])).toBe("foo");
            expect(uniquify("foo", {})).toBe("foo");
        });

        it("appends -2 on first collision", function () {
            expect(uniquify("foo", new Set(["foo"]))).toBe("foo-2");
            expect(uniquify("foo", ["foo"])).toBe("foo-2");
            expect(uniquify("foo", { foo: true })).toBe("foo-2");
        });

        it("walks the suffix sequence", function () {
            expect(uniquify("foo", new Set(["foo", "foo-2"]))).toBe("foo-3");
            expect(uniquify("foo", new Set(["foo", "foo-2", "foo-3"]))).toBe("foo-4");
        });

        it("skips suffix gaps", function () {
            // foo-2 is free even though foo-3 is taken; the function uses the
            // first free slot in sequence.
            expect(uniquify("foo", new Set(["foo", "foo-3"]))).toBe("foo-2");
        });

        it("handles empty/null slug input", function () {
            expect(uniquify("", new Set(["x"]))).toBe("");
            expect(uniquify(null, new Set(["x"]))).toBe(null);
        });
    });
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/mindmap/test/test-slide-filters.js":{"title":"$:/plugins/rimir/mindmap/test/test-slide-filters.js","text":"/*\
title: $:/plugins/rimir/mindmap/test/test-slide-filters.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Unit tests for filters/slides.js. Operators take owner-tiddler titles as input
and consult mm.slide-order on each — exercise against a fresh wiki so the
look-ups go through the real getTiddler / parseStringArray paths.

\*/

"use strict";

describe("mindmap-slide-filters", function () {
    var ops = require("$:/plugins/rimir/mindmap/filters/slides.js");
    var lib = require("$:/plugins/rimir/mindmap/lib/slide-tiddlers.js");

    function setupWiki(tiddlers) {
        var wiki = new $tw.Wiki();
        wiki.addTiddlers(tiddlers || []);
        wiki.addIndexersToWiki();
        return wiki;
    }

    function ownerSeed() {
        return [{ title: "knowledge/llm/foo", "kn.type": "note", text: "" }];
    }

    function source(titles) {
        return function (callback) {
            for (var i = 0; i < titles.length; i++) { callback(null, titles[i]); }
        };
    }

    describe("mm-slides", function () {
        it("returns slides in mm.slide-order order", function () {
            var wiki = setupWiki(ownerSeed());
            var t1 = lib.addSlide(wiki, "knowledge/llm/foo");
            var t2 = lib.addSlide(wiki, "knowledge/llm/foo");
            var out = ops["mm-slides"](source(["knowledge/llm/foo"]), {}, { wiki: wiki });
            expect(out).toEqual([t1, t2]);
        });

        it("returns nothing for owners with no slides", function () {
            var wiki = setupWiki(ownerSeed());
            expect(ops["mm-slides"](source(["knowledge/llm/foo"]), {}, { wiki: wiki })).toEqual([]);
        });

        it("concatenates results across multiple input owners", function () {
            var wiki = setupWiki(ownerSeed().concat([
                { title: "knowledge/llm/bar", "kn.type": "note", text: "" }
            ]));
            var t1 = lib.addSlide(wiki, "knowledge/llm/foo");
            var t2 = lib.addSlide(wiki, "knowledge/llm/bar");
            var out = ops["mm-slides"](source(["knowledge/llm/foo", "knowledge/llm/bar"]), {}, { wiki: wiki });
            expect(out).toEqual([t1, t2]);
        });
    });

    describe("mm-slide-count", function () {
        it("returns 0 for owners with no slides", function () {
            var wiki = setupWiki(ownerSeed());
            expect(ops["mm-slide-count"](source(["knowledge/llm/foo"]), {}, { wiki: wiki }))
                .toEqual(["0"]);
        });

        it("returns the slide count per input title", function () {
            var wiki = setupWiki(ownerSeed());
            lib.addSlide(wiki, "knowledge/llm/foo");
            lib.addSlide(wiki, "knowledge/llm/foo");
            expect(ops["mm-slide-count"](source(["knowledge/llm/foo"]), {}, { wiki: wiki }))
                .toEqual(["2"]);
        });
    });

    describe("mm-has-slides", function () {
        it("returns 'no' for owners with no slides", function () {
            var wiki = setupWiki(ownerSeed());
            expect(ops["mm-has-slides"](source(["knowledge/llm/foo"]), {}, { wiki: wiki }))
                .toEqual(["no"]);
        });

        it("returns 'yes' once at least one slide exists", function () {
            var wiki = setupWiki(ownerSeed());
            lib.addSlide(wiki, "knowledge/llm/foo");
            expect(ops["mm-has-slides"](source(["knowledge/llm/foo"]), {}, { wiki: wiki }))
                .toEqual(["yes"]);
        });
    });
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/mindmap/test/test-slide-tiddlers.js":{"title":"$:/plugins/rimir/mindmap/test/test-slide-tiddlers.js","text":"/*\
title: $:/plugins/rimir/mindmap/test/test-slide-tiddlers.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Unit tests for lib/slide-tiddlers.js. The module's wiki-aware operations
(getSlideTitles, addSlide, removeSlide, moveSlide) are exercised against a
fresh `new $tw.Wiki()` — same pattern as test-knowledge-tree-apply.

\*/

"use strict";

describe("mindmap-slide-tiddlers", function () {
    var lib = require("$:/plugins/rimir/mindmap/lib/slide-tiddlers.js");

    function setupWiki(tiddlers) {
        var wiki = new $tw.Wiki();
        wiki.addTiddlers(tiddlers || []);
        wiki.addIndexersToWiki();
        return wiki;
    }

    function ownerSeed() {
        return [
            { title: "knowledge/llm/foo", "kn.type": "note", text: "owner body" }
        ];
    }

    describe("slideTitleFor / ownerTitleFor", function () {
        it("composes a slide title from owner + slug", function () {
            expect(lib.slideTitleFor("knowledge/llm/foo", "slide-1"))
                .toBe("knowledge/llm/foo/slides/slide-1");
        });

        it("returns null when either arg is missing", function () {
            expect(lib.slideTitleFor("", "slide-1")).toBe(null);
            expect(lib.slideTitleFor("knowledge/llm/foo", "")).toBe(null);
        });

        it("ownerTitleFor inverts slideTitleFor", function () {
            expect(lib.ownerTitleFor("knowledge/llm/foo/slides/slide-1"))
                .toBe("knowledge/llm/foo");
        });

        it("ownerTitleFor returns null for non-slide titles", function () {
            expect(lib.ownerTitleFor("knowledge/llm/foo")).toBe(null);
            expect(lib.ownerTitleFor("")).toBe(null);
        });
    });

    describe("isSlideTiddler", function () {
        it("detects via kn.type=slide", function () {
            var t = new $tw.Tiddler({ title: "x", "kn.type": "slide" });
            expect(lib.isSlideTiddler(t)).toBe(true);
        });

        it("detects via slide tag", function () {
            var t = new $tw.Tiddler({ title: "x", tags: "$:/tags/rimir/mindmap/slide" });
            expect(lib.isSlideTiddler(t)).toBe(true);
        });

        it("returns false for ordinary tiddlers", function () {
            var t = new $tw.Tiddler({ title: "x", "kn.type": "note" });
            expect(lib.isSlideTiddler(t)).toBe(false);
            expect(lib.isSlideTiddler(null)).toBe(false);
        });
    });

    describe("freshSlideSlug", function () {
        it("returns slide-1 when no slides exist", function () {
            var wiki = setupWiki(ownerSeed());
            expect(lib.freshSlideSlug(wiki, "knowledge/llm/foo")).toBe("slide-1");
        });

        it("skips over existing slugs", function () {
            var wiki = setupWiki(ownerSeed().concat([
                { title: "knowledge/llm/foo/slides/slide-1",
                  "kn.type": "slide",
                  tags: "$:/tags/rimir/mindmap/slide",
                  "mm.slide-of": "knowledge/llm/foo" },
                { title: "knowledge/llm/foo/slides/slide-2",
                  "kn.type": "slide",
                  tags: "$:/tags/rimir/mindmap/slide",
                  "mm.slide-of": "knowledge/llm/foo" }
            ]));
            expect(lib.freshSlideSlug(wiki, "knowledge/llm/foo")).toBe("slide-3");
        });

        it("fills gaps (slide-2 missing while slide-1 + slide-3 exist)", function () {
            // freshSlideSlug picks the lowest-N slug that doesn't collide —
            // so a manually-deleted slide-2 gets reused.
            var wiki = setupWiki(ownerSeed().concat([
                { title: "knowledge/llm/foo/slides/slide-1",
                  "kn.type": "slide",
                  tags: "$:/tags/rimir/mindmap/slide" },
                { title: "knowledge/llm/foo/slides/slide-3",
                  "kn.type": "slide",
                  tags: "$:/tags/rimir/mindmap/slide" }
            ]));
            expect(lib.freshSlideSlug(wiki, "knowledge/llm/foo")).toBe("slide-2");
        });
    });

    describe("addSlide", function () {
        it("creates a slide tiddler with all expected fields", function () {
            var wiki = setupWiki(ownerSeed());
            var t = lib.addSlide(wiki, "knowledge/llm/foo");
            expect(t).toBe("knowledge/llm/foo/slides/slide-1");
            var slide = wiki.getTiddler(t);
            expect(slide).toBeTruthy();
            expect(slide.fields["kn.type"]).toBe("slide");
            expect(slide.fields["mm.slide-of"]).toBe("knowledge/llm/foo");
            expect(slide.fields["mm.slide-layout"]).toBe("default");
            // Tags should include the slide tag.
            var tags = $tw.utils.parseStringArray(slide.fields.tags || "");
            expect(tags.indexOf("$:/tags/rimir/mindmap/slide")).toBeGreaterThan(-1);
        });

        it("appends the slide title to the owner's mm.slide-order list", function () {
            var wiki = setupWiki(ownerSeed());
            lib.addSlide(wiki, "knowledge/llm/foo");
            lib.addSlide(wiki, "knowledge/llm/foo");
            var owner = wiki.getTiddler("knowledge/llm/foo");
            var order = $tw.utils.parseStringArray(owner.fields["mm.slide-order"] || "");
            expect(order).toEqual([
                "knowledge/llm/foo/slides/slide-1",
                "knowledge/llm/foo/slides/slide-2"
            ]);
        });

        it("honors opts.layout / opts.text / opts.caption", function () {
            var wiki = setupWiki(ownerSeed());
            var t = lib.addSlide(wiki, "knowledge/llm/foo", {
                layout: "title", text: "# Hello", caption: "intro"
            });
            var slide = wiki.getTiddler(t);
            expect(slide.fields["mm.slide-layout"]).toBe("title");
            expect(slide.fields.text).toBe("# Hello");
            expect(slide.fields.caption).toBe("intro");
        });

        it("returns null when the owner tiddler does not exist", function () {
            var wiki = setupWiki([]);
            expect(lib.addSlide(wiki, "does/not/exist")).toBe(null);
        });
    });

    describe("getSlideTitles", function () {
        it("returns slides in the order recorded by mm.slide-order", function () {
            var wiki = setupWiki(ownerSeed());
            lib.addSlide(wiki, "knowledge/llm/foo");
            lib.addSlide(wiki, "knowledge/llm/foo");
            lib.addSlide(wiki, "knowledge/llm/foo");
            expect(lib.getSlideTitles(wiki, "knowledge/llm/foo")).toEqual([
                "knowledge/llm/foo/slides/slide-1",
                "knowledge/llm/foo/slides/slide-2",
                "knowledge/llm/foo/slides/slide-3"
            ]);
        });

        it("filters out order entries that no longer resolve to tiddlers", function () {
            // Manually craft an order with a stale entry.
            var wiki = setupWiki(ownerSeed().concat([
                { title: "knowledge/llm/foo/slides/slide-1",
                  "kn.type": "slide",
                  tags: "$:/tags/rimir/mindmap/slide" }
            ]));
            wiki.addTiddler(new $tw.Tiddler(wiki.getTiddler("knowledge/llm/foo"), {
                "mm.slide-order": "knowledge/llm/foo/slides/slide-1 knowledge/llm/foo/slides/stale"
            }));
            expect(lib.getSlideTitles(wiki, "knowledge/llm/foo")).toEqual([
                "knowledge/llm/foo/slides/slide-1"
            ]);
        });

        it("returns [] for owners without any slides", function () {
            var wiki = setupWiki(ownerSeed());
            expect(lib.getSlideTitles(wiki, "knowledge/llm/foo")).toEqual([]);
        });
    });

    describe("removeSlide", function () {
        it("deletes the slide tiddler and scrubs the owner's order list", function () {
            var wiki = setupWiki(ownerSeed());
            var t1 = lib.addSlide(wiki, "knowledge/llm/foo");
            var t2 = lib.addSlide(wiki, "knowledge/llm/foo");
            expect(lib.removeSlide(wiki, t1)).toBe(true);
            expect(wiki.getTiddler(t1)).toBeUndefined();
            // t2 still present and remains in the order.
            expect(wiki.getTiddler(t2)).toBeTruthy();
            var order = $tw.utils.parseStringArray(
                wiki.getTiddler("knowledge/llm/foo").fields["mm.slide-order"] || "");
            expect(order).toEqual([t2]);
        });

        it("is a no-op when the slide title doesn't exist", function () {
            var wiki = setupWiki(ownerSeed());
            expect(lib.removeSlide(wiki, "knowledge/llm/foo/slides/nope")).toBe(false);
        });
    });

    describe("moveSlide", function () {
        it("moves a slide by the supplied delta", function () {
            var wiki = setupWiki(ownerSeed());
            var t1 = lib.addSlide(wiki, "knowledge/llm/foo");
            var t2 = lib.addSlide(wiki, "knowledge/llm/foo");
            var t3 = lib.addSlide(wiki, "knowledge/llm/foo");
            expect(lib.moveSlide(wiki, t3, -1)).toBe(true);
            expect(lib.getSlideTitles(wiki, "knowledge/llm/foo")).toEqual([t1, t3, t2]);
        });

        it("saturates at list bounds (moving the first slide up is a no-op)", function () {
            var wiki = setupWiki(ownerSeed());
            var t1 = lib.addSlide(wiki, "knowledge/llm/foo");
            lib.addSlide(wiki, "knowledge/llm/foo");
            expect(lib.moveSlide(wiki, t1, -1)).toBe(false);
        });

        it("returns false when the slide isn't in the order", function () {
            var wiki = setupWiki(ownerSeed());
            lib.addSlide(wiki, "knowledge/llm/foo");
            expect(lib.moveSlide(wiki, "knowledge/llm/foo/slides/foreign", 1, "knowledge/llm/foo")).toBe(false);
        });
    });
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/mindmap/test/test-structural-routing.js":{"title":"$:/plugins/rimir/mindmap/test/test-structural-routing.js","text":"/*\
title: $:/plugins/rimir/mindmap/test/test-structural-routing.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Unit tests for structural-ops.routeOp.

\*/

"use strict";

describe("mindmap-structural-routing", function () {
    var router = require("$:/plugins/rimir/mindmap/structural-ops.js");

    var STRUCTURAL_PRODUCER = {
        capabilities: {
            structural: true,
            structuralOps: ["rename", "reparent", "addNode", "removeNode"]
        },
        titleForOp: function (op) { return "knowledge/test/" + (op.id || ""); }
    };

    var OVERLAY_PRODUCER = {
        capabilities: {}
    };

    function fakeWiki(titles) {
        return {
            filterTiddlers: function (filter) {
                // Trivial filter executor sufficient for these tests: handles
                // the single shape used by countAffectedDescendants.
                var m = filter.match(/prefix\[([^\]]+)\]/);
                if (!m) { return []; }
                var prefix = m[1];
                return titles.filter(function (t) { return t.indexOf(prefix) === 0; });
            }
        };
    }

    it("routes structural-whitelisted ops to structural", function () {
        var result = router.routeOp(
            { op: "rename", id: "foo", label: "Bar" },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki([]) }
        );
        expect(result.mode).toBe("structural");
    });

    it("routes setAttr to overlay even on structural producer", function () {
        var result = router.routeOp(
            { op: "setAttr", id: "foo", key: "core:collapsed", value: true },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki([]) }
        );
        expect(result.mode).toBe("overlay");
    });

    it("routes reorder to overlay (sibling order not tracked for structural)", function () {
        var result = router.routeOp(
            { op: "reorder", parent: "p", order: ["a", "b"] },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki([]) }
        );
        expect(result.mode).toBe("overlay");
    });

    it("routes every op to overlay for a non-structural producer", function () {
        ["rename", "reparent", "addNode", "removeNode", "setAttr"].forEach(function (k) {
            var result = router.routeOp(
                { op: k, id: "x" },
                OVERLAY_PRODUCER,
                { wiki: fakeWiki([]) }
            );
            expect(result.mode).toBe("overlay");
        });
    });

    it("drops malformed ops", function () {
        expect(router.routeOp(null, STRUCTURAL_PRODUCER, {}).mode).toBe("drop");
        expect(router.routeOp({}, STRUCTURAL_PRODUCER, {}).mode).toBe("drop");
    });

    it("falls through unknown ops to overlay (round-trip safety)", function () {
        var result = router.routeOp(
            { op: "unknownFutureOp", id: "x" },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki([]) }
        );
        expect(result.mode).toBe("overlay");
    });

    it("defers structural ops whose cascade exceeds threshold", function () {
        var titles = [
            "knowledge/test/foo/a",
            "knowledge/test/foo/b",
            "knowledge/test/foo/c",
            "knowledge/test/foo/a/x",
            "knowledge/test/foo/a/y"
        ];
        var result = router.routeOp(
            { op: "rename", id: "foo", label: "bar" },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki(titles), cascadeThreshold: 3 }
        );
        expect(result.mode).toBe("deferred");
        expect(result.count).toBe(5);
        expect(result.reason).toBe("cascade-threshold");
    });

    it("does not defer when cascade is at or below threshold", function () {
        var titles = ["knowledge/test/foo/a", "knowledge/test/foo/b"];
        var result = router.routeOp(
            { op: "rename", id: "foo", label: "bar" },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki(titles), cascadeThreshold: 2 }
        );
        expect(result.mode).toBe("structural");
    });

    it("does not defer addNode (no descendants to cascade)", function () {
        var titles = ["knowledge/test/foo/a", "knowledge/test/foo/b"];
        // addNode op MUST still route as structural even when target prefix
        // matches lots of titles — those titles aren't cascade victims.
        var result = router.routeOp(
            { op: "addNode", parent: "foo", node: { id: "new", label: "X" } },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki(titles), cascadeThreshold: 1 }
        );
        expect(result.mode).toBe("structural");
    });

    it("skips cascade-threshold for rename when label-field is non-title", function () {
        // 5 descendants but rename in caption-mode only touches one field on
        // one tiddler — no cascade, no confirm modal.
        var titles = [
            "knowledge/test/foo/a", "knowledge/test/foo/b", "knowledge/test/foo/c",
            "knowledge/test/foo/d", "knowledge/test/foo/e"
        ];
        var result = router.routeOp(
            { op: "rename", id: "foo", label: "new label" },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki(titles), cascadeThreshold: 2, args: { "label-field": "caption" } }
        );
        expect(result.mode).toBe("structural");
    });

    it("still defers reparent in non-title label-field mode (reparent always cascades)", function () {
        var titles = [
            "knowledge/test/foo/a", "knowledge/test/foo/b", "knowledge/test/foo/c",
            "knowledge/test/foo/d", "knowledge/test/foo/e"
        ];
        var result = router.routeOp(
            { op: "reparent", id: "foo", newParent: "bar" },
            STRUCTURAL_PRODUCER,
            { wiki: fakeWiki(titles), cascadeThreshold: 2, args: { "label-field": "caption" } }
        );
        expect(result.mode).toBe("deferred");
    });
});
